<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantConfig\Domain\ValueObject\Accessor\TenantConfigMagicLinkExpiryMinutesAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantConfigMagicLinkExpiryMinutesAccessor trait.
 *
 * Covers null default, string/VO assignment via withMagicLinkExpiryMinutes,
 * getMagicLinkExpiryMinutes/magicLinkExpiryMinutes accessors, and isMagicLinkExpiryMinutesChanged with/without original.
 */
class TenantConfigMagicLinkExpiryMinutesAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withMagicLinkExpiryMinutes creates a new instance with the MagicLinkExpiryMinutes set
     * from a string value, and getMagicLinkExpiryMinutes returns the primitive string.
     */
    public function testWithMagicLinkExpiryMinutesFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigMagicLinkExpiryMinutesAccessorUnitTest();

        // Act
        $result = $holder->withMagicLinkExpiryMinutes(1);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(1, $result->getMagicLinkExpiryMinutes());
    }
    /**
     * Asserts that withmagicLinkExpiryMinutes has access to the value object
     * from a string value, and getMagicLinkExpiryMinutes returns the primitive string.
     */
    public function testWithMagicLinkExpiryMinutesFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigMagicLinkExpiryMinutesAccessorUnitTest();

        // Act
        $result = $holder->withMagicLinkExpiryMinutes(1);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(1, $result->magicLinkExpiryMinutes()->value());
    }
    public function testChangedMagicLinkExpiryMinutes(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigMagicLinkExpiryMinutesAccessorUnitTest()->withMagicLinkExpiryMinutes(1);
        $original = $holder->withMagicLinkExpiryMinutes(1);
        $same = $holder->withMagicLinkExpiryMinutes(1);
        $modified = $holder->withMagicLinkExpiryMinutes(2);

        // Act
        $withSame = $original->isMagicLinkExpiryMinutesChanged($same);
        $withDiferent = $original->isMagicLinkExpiryMinutesChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantConfigMagicLinkExpiryMinutesAccessorUnitTest
{
    use TenantConfigMagicLinkExpiryMinutesAccessor;
}
